import{_ as a,c as r,o as t,ag as i}from"./chunks/framework.DQvKz0xt.js";const v=JSON.parse('{"title":"界面概览 (Interface Overview) - Rive 编辑器","description":"Rive 的界面精简高效，只在需要时显示必要的内容。它分为几个主要面板，详见下文。 工具栏显示了你可以在舞台 (Stage) 上用于创建、绑定和操纵项目的工具。除了这些工具外，工具栏还包含各种选项，允许你自定义文件的外观、设置主画板以及导出或分享文件。","frontmatter":{"title":"界面概览 (Interface Overview) - Rive 编辑器","description":"Rive 的界面精简高效，只在需要时显示必要的内容。它分为几个主要面板，详见下文。 工具栏显示了你可以在舞台 (Stage) 上用于创建、绑定和操纵项目的工具。除了这些工具外，工具栏还包含各种选项，允许你自定义文件的外观、设置主画板以及导出或分享文件。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 界面面板, 界面概览"}]]},"headers":[],"relativePath":"editor/interface-overview/overview.md","filePath":"editor/interface-overview/overview.md","lastUpdated":1774838907000}'),o={name:"editor/interface-overview/overview.md"};function n(h,e,p,s,c,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<p>界面概览</p><h1 id="界面概览-interface-overview" tabindex="-1">界面概览 (Interface Overview) <a class="header-anchor" href="#界面概览-interface-overview" aria-label="Permalink to &quot;界面概览 (Interface Overview)&quot;">​</a></h1><p>Rive 的界面精简高效，只在需要时显示必要的内容。它分为几个主要面板，详见下文。</p><h2 id="​-工具栏-toolbar" tabindex="-1"><a href="#toolbar">​</a> 工具栏 (Toolbar) <a class="header-anchor" href="#​-工具栏-toolbar" aria-label="Permalink to &quot;[​](#toolbar) 工具栏 (Toolbar)&quot;">​</a></h2><p>工具栏显示了你可以在舞台 (Stage) 上用于创建、绑定和操纵项目的工具。除了这些工具外，工具栏还包含各种选项，允许你自定义文件的外观、设置主画板以及导出或分享文件。 <img src="https://help.rive.app/images/toolbar.png" alt="工具栏 Pn"> 在工具栏页面了解更多信息。 [## 工具栏 (Toolbar)</p><p><a href="/docs/editor/interface-overview/toolbar">从 Rive 编辑器工具栏访问设计和动画工具</a></p><h2 id="​-层级面板-hierarchy" tabindex="-1"><a href="#hierarchy">​</a> 层级面板 (Hierarchy) <a class="header-anchor" href="#​-层级面板-hierarchy" aria-label="Permalink to &quot;[​](#hierarchy) 层级面板 (Hierarchy)&quot;">​</a></h2><p>组成文件的所有对象、资产、控制和动画都显示在层级面板中。你还可以在这里找到资产面板 (Assets Panel) 和数据面板 (Data Panel)。 <img src="https://help.rive.app/images/hierarchy.png" alt="层级面板 Pn"> [## 层级面板 (Hierarchy)</p><p><a href="/docs/editor/interface-overview/hierarchy">层级面板是一个树状视图，它既显示了舞台上对象之间的父子关系，也显示了它们的渲染顺序。通过观看视频或阅读下文来了解层级面板。</a></p><h2 id="​-检查器-inspector" tabindex="-1"><a href="#inspector">​</a> 检查器 (Inspector) <a class="header-anchor" href="#​-检查器-inspector" aria-label="Permalink to &quot;[​](#inspector) 检查器 (Inspector)&quot;">​</a></h2><p>检查器允许你调整当前选中对象的属性，无论该对象是在舞台上、时间轴 (Timeline) 上还是状态机 (State Machine) 中。 <img src="https://help.rive.app/images/inspector.png" alt="检查器 Pn"> 在检查器页面了解更多信息。 [## 检查器 (Inspector)</p><p><a href="/docs/editor/interface-overview/inspector">对象的待编辑属性可以在检查器中找到。检查器会根据你选择的对象以及你在编辑器中所处的位置动态变化。</a></p><h2 id="​-舞台-stage" tabindex="-1"><a href="#stage">​</a> 舞台 (Stage) <a class="header-anchor" href="#​-舞台-stage" aria-label="Permalink to &quot;[​](#stage) 舞台 (Stage)&quot;">​</a></h2><p>舞台是指工具栏、层级面板和检查器之间的中央区域。在这里，你可以创建画板 (Artboards)，它是你在 Rive 中进行设计和制作动画的基础。 <img src="https://help.rive.app/images/stage.png" alt="舞台 Pn"> 在舞台页面了解更多信息： [## 舞台 (Stage)</p><p><a href="/docs/editor/interface-overview/stage">舞台是一个无限的画布，你可以在其中放置包含所有图形的画板。</a></p><h2 id="​-时间轴-timeline" tabindex="-1"><a href="#timeline">​</a> 时间轴 (Timeline) <a class="header-anchor" href="#​-时间轴-timeline" aria-label="Permalink to &quot;[​](#timeline) 时间轴 (Timeline)&quot;">​</a></h2><p><img src="https://help.rive.app/images/CleanShot2025-06-26at11.33.04@2x.png" alt="时间轴示例 Pn"> 进入动画模式 (Animate Mode) 后，时间轴会从屏幕底部升起。在这里，你可以创建新的动画状态、访问播放控制、设置以及为对象参数设置关键帧 (Keyframes)。从左侧列表中选择一个时间轴，可以在各个时间轴之间切换。 在时间轴页面了解更多信息： [## 时间轴 (Timeline)</p><p><a href="/docs/editor/animate-mode/timeline">Rive 界面显示了一个带有播放控制的时间轴，以及用于在动画模式下进行当前动画配置的选项。时间轴左侧显示了所有动画的列表。请记住，这些都是当前活动画板的动画。</a></p><h2 id="​-状态机图表-state-machine-graph" tabindex="-1"><a href="#state-machine-graph">​</a> 状态机图表 (State Machine Graph) <a class="header-anchor" href="#​-状态机图表-state-machine-graph" aria-label="Permalink to &quot;[​](#state-machine-graph) 状态机图表 (State Machine Graph)&quot;">​</a></h2><p><img src="https://help.rive.app/images/CleanShot2025-06-26at11.33.28@2x.png" alt="状态机示例 Pn"> 当选中状态机时，时间轴会被图表取代。这就是你进行状态机工作的地方。 在状态机页面了解更多信息。 [## 状态机 (State Machine)</p><p><a href="/docs/editor/state-machine/overview">状态机是一种直观地将动画连接在一起并定义驱动过渡逻辑的方式。</a></p>',21)])])}const m=a(o,[["render",n]]);export{v as __pageData,m as default};
